# Integer polynomials modulo z*z=z: symbolic Boolean algebra only.
def add(*polys):
    result = {}
    for p in polys:
        for term, coefficient in p.items():
            result[term] = result.get(term, 0) + coefficient
    return {t: c for t, c in result.items() if c}

def scale(p, coefficient):
    return {t: c * coefficient for t, c in p.items() if c * coefficient}

def mul(p, q):
    result = {}
    for a, ca in p.items():
        for b, cb in q.items():
            term = a | b
            result[term] = result.get(term, 0) + ca * cb
    return {t: c for t, c in result.items() if c}

ONE = {frozenset(): 1}
ZERO = {}

def variable(i):
    return {frozenset([i]): 1}

def complement(p):
    return add(ONE, scale(p, -1))

# Analytic hinge decomposition using formal generating polynomials.
# No input examples or network activations are computed.
def hinge_polynomial(coefficients, bias):
    distribution = {0: ONE}
    for index, coefficient in coefficients.items():
        literal = variable(index)
        if coefficient < 0:
            bias += coefficient
            coefficient = -coefficient
            literal = complement(literal)
        updated = {}
        for degree, polynomial in distribution.items():
            updated[degree] = add(
                updated.get(degree, ZERO),
                mul(polynomial, complement(literal)),
            )
            shifted = degree + coefficient
            updated[shifted] = add(
                updated.get(shifted, ZERO),
                mul(polynomial, literal),
            )
        distribution = updated
    return add(*[
        scale(polynomial, max(0, degree + bias))
        for degree, polynomial in distribution.items()
    ])

def decode_gate(polynomial, previous):
    support = sorted(set().union(*polynomial.keys())) if polynomial else []
    candidates = [(ZERO, False), (ONE, True)]
    for i in support:
        a = variable(i)
        candidates.extend([
            (a, previous[i]),
            (complement(a), ("not", previous[i])),
        ])
    for i, j in itertools.permutations(support, 2):
        a, b = variable(i), variable(j)
        ab = mul(a, b)
        either = add(a, b, scale(ab, -1))
        exclusive = add(a, b, scale(ab, -2))
        for operation, p in [
            ("and", ab), ("or", either), ("xor", exclusive),
            ("nand", complement(ab)), ("nor", complement(either)),
        ]:
            candidates.append((p, (operation, previous[i], previous[j])))
    for i, j, k in itertools.permutations(support, 3):
        a, b, c = variable(i), variable(j), variable(k)
        majority = add(
            mul(a, b), mul(a, c), mul(b, c),
            scale(mul(mul(a, b), c), -2),
        )
        mux = add(mul(a, b), mul(complement(a), c))
        candidates.extend([
            (majority, ("majority", previous[i], previous[j], previous[k])),
            (mux, ("mux", previous[i], previous[j], previous[k])),
        ])
    for candidate, expression in candidates:
        if candidate == polynomial:
            return expression
    raise ValueError("Unrecognized symbolic gate")

