# Evaluate only the recovered Boolean expression.
def evaluate(node, bits):
    if isinstance(node, bool):
        return node
    operation = node[0]
    if operation == "input":
        return bool(bits[node[1]])
    values = [evaluate(child, bits) for child in node[1:]]
    if operation == "not":
        return not values[0]
    if operation == "and":
        return values[0] and values[1]
    if operation == "or":
        return values[0] or values[1]
    if operation == "xor":
        return values[0] != values[1]
    if operation == "nand":
        return not (values[0] and values[1])
    if operation == "nor":
        return not (values[0] or values[1])
    if operation == "majority":
        return sum(values) >= 2
    if operation == "mux":
        return values[1] if values[0] else values[2]
    raise ValueError(operation)

